import{_ as i,o as a,c as t,a2 as o}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"Prestazioni (M7-WP1)","description":"","frontmatter":{},"headers":[],"relativePath":"perf/index.md","filePath":"perf/README.md"}'),n={name:"perf/index.md"};function s(d,e,c,r,l,p){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="prestazioni-m7-wp1" tabindex="-1">Prestazioni (M7-WP1) <a class="header-anchor" href="#prestazioni-m7-wp1" aria-label="Permalink to &quot;Prestazioni (M7-WP1)&quot;">​</a></h1><p>Obiettivi dall&#39;Appendice A dello spec, misure e come ripeterle. Le cifre sono quelle realmente misurate; dove un obiettivo non è raggiunto o non è misurabile qui è scritto.</p><h2 id="come-si-esegue" tabindex="-1">Come si esegue <a class="header-anchor" href="#come-si-esegue" aria-label="Permalink to &quot;Come si esegue&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PERF_NOTES=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # indice, ricerca, apertura nota, apertura vault, creazione/rinomina, scansione sync, grafo 10k → .perf/results-50000.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf-check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PERF_NOTES=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [PERF_TOLERANCE=25]   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># confronto con docs/perf/baseline-50000.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf-data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PERF_NOTES=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # solo il dataset (cache in .perf/vault-N, mai committato)</span></span></code></pre></div><ul><li>Dataset: <code>apps/desktop/internal/perf/dataset</code> (seed fisso, stesso vault a ogni esecuzione). Note con dimensioni log-normali (mediana ≈ 1,8 KB, coda fino a 600 KB), frontmatter, intestazioni, tag, wikilink con grado entrante a legge di potenza (hub e coda lunga), link fantasma, riferimenti ad allegati. 50.000 note = 168 MB, ≈ 395.000 link.</li><li>Variabili del test (<code>internal/perf/perf_test.go</code>): <code>CLARAE_PERF_NOTES</code>, <code>CLARAE_PERF_DIR</code>, <code>CLARAE_PERF_GRAPH_NOTES</code>, <code>CLARAE_PERF_OUT</code>, <code>CLARAE_PERF_KEEP_INDEX</code>, <code>CLARAE_PERF_CPUPROFILE</code>, <code>CLARAE_PERF_INDEX_PROFILE</code>.</li><li>UI (Chromium headless su mock dei binding): <code>CLARAE_UI_BENCH=1 yarn workspace @clarae/desktop-frontend exec playwright test e2e/ui-perf.spec.ts</code> (<code>CLARAE_UI_BENCH_NOTES</code>, <code>CLARAE_UI_BENCH_NOTE_KB</code>, <code>CLARAE_UI_BENCH_OUT</code>).</li><li>Cloud: vedi la sezione sotto.</li><li>Esecuzione: a mano (<code>task perf</code>, k6 e <code>perfcheck</code>); il workflow notturno <code>nightly-perf.yml</code> è stato rimosso il 2026-10-30 e non c&#39;è più un job che produca artifact. Le baseline di CI sono <code>docs/perf/baseline-ci-&lt;note&gt;.json</code>: vanno create alla prima esecuzione su una macchina di riferimento, perché quella di questo repository è di un&#39;altra macchina.</li></ul><h2 id="macchina-e-metodo" tabindex="-1">Macchina e metodo <a class="header-anchor" href="#macchina-e-metodo" aria-label="Permalink to &quot;Macchina e metodo&quot;">​</a></h2><p>MacBook Apple M4 (10 core), 32 GB, macOS 27.0.1, SSD, Go 1.26.0; Chromium di Playwright headless. <strong>La macchina era condivisa con altre build: load average 11-15 durante le misure</strong>, quindi i tempi sono pessimistici e variano di decine di percento da una corsa all&#39;altra (la stessa indicizzazione da 50k ha impiegato 72,6 s e 85,9 s). Ricerca: mediana di 7 esecuzioni dopo una di riscaldamento (cache pagine del sistema e cache dei candidati). Nessuna cifra è stimata o estrapolata.</p><h2 id="tabella-obiettivi" tabindex="-1">Tabella obiettivi <a class="header-anchor" href="#tabella-obiettivi" aria-label="Permalink to &quot;Tabella obiettivi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Obiettivo (spec)</th><th>Misurato</th><th>Macchina</th><th>Stato</th></tr></thead><tbody><tr><td>Indice 50.000 note &lt; 3 min</td><td><strong>72,6 s</strong> (prima: non terminato dopo 2 h 23 min, 38.000 file)</td><td>M4, carica</td><td>raggiunto</td></tr><tr><td>Indice incrementale &lt; 100 ms/nota</td><td><strong>3,8 ms</strong> mediana, 34 ms p95 (prima: 280 ms a 5k note, cresceva col vault)</td><td>M4, carica</td><td>raggiunto</td></tr><tr><td>Ricerca &lt; 200 ms su 50.000 note</td><td>testo: <strong>27-143 ms</strong> mediana; frase 63 ms; <code>line:</code> 81 ms; proprietà+testo 143 ms (prima: 0,6-2,8 s)</td><td>M4, carica</td><td>raggiunto, tranne regex</td></tr><tr><td>Ricerca con regex su tutto il vault</td><td>461 ms mediana (578 ms p95)</td><td>M4, carica</td><td><strong>non raggiunto</strong></td></tr><tr><td>Apertura nota &lt; 150 ms (parte backend)</td><td><strong>0,7 ms</strong> mediana, 1,6 ms p95 (lettura + parse + link uscenti + backlink); menzioni non collegate 15 ms</td><td>M4</td><td>raggiunto (solo Go)</td></tr><tr><td>Avvio a freddo &lt; 3 s</td><td>parte Go: <strong>147 ms</strong> (store + albero di 50.968 voci + indice pronto); cache di ricerca 0,76 s in background</td><td>M4</td><td>parte Go raggiunta; <strong>avvio completo non misurato</strong> (serve la webview reale)</td></tr><tr><td>Grafo 10.000 nodi ≥ 30 fps</td><td><code>Build</code> 10k: <strong>99 ms</strong>; rendering e layout come in <code>docs/qa/m6-graph-benchmark.md</code> (60 fps pan/zoom, Chromium headless)</td><td>M4</td><td>riuso M6</td></tr><tr><td>Digitazione senza lag su nota ≤ 1 MB</td><td>1 MB, Live Preview di CodeMirror: latenza tasto→2 frame mediana <strong>24,4 ms</strong>, p95 32,9 ms; nota da 1 KB: 24,1 / 31,8 ms (il pavimento di 2 frame a 60 Hz è ≈ 33 ms). <strong>Misurato sul Live Preview di CodeMirror, rimosso in M16 (2026-11-12): da rimisurare sul Live di Milkdown.</strong> Una nota oltre 250.000 caratteri si apre in Sorgente (CodeMirror); in A-W8 (ADR-0049, Chromium headless, macchina carica) la digitazione in Live ha dato p50/p95 di 17–19 / 31–33 ms su note da 5 e 200 kB, e in Sorgente 26 / 33 ms su 1 MB</td><td>M4, Chromium headless</td><td>nessun lag misurabile sul vecchio Live; da rimisurare sul Live attuale e da confermare sulla webview reale</td></tr><tr><td>Albero file con 50.000 note</td><td>render 856 ms (prima 3.319 ms), 37 righe nel DOM (prima 50.715), espandi/comprimi 6 ms (prima 642 ms); 10k: 736 ms prima</td><td>M4, Chromium headless</td><td>migliorato</td></tr><tr><td>Memoria dell&#39;indice</td><td>cache di ricerca ≈ <strong>210 MB</strong> di heap a 50k; picco runtime Go in indicizzazione 161 MB; <code>index.db</code> 894 MB su disco (5,3× il testo)</td><td>M4</td><td>misurato, vedi limiti</td></tr><tr><td>Cloud p95 <code>changes</code> &lt; 200 ms, <code>commit</code> &lt; 500 ms a 1.000 utenti</td><td>k6 <strong>non eseguito</strong> (vedi sotto). Test Go esistente, 8 client: changes p95 13 ms, commit 50 op p95 216 ms. Misto piccolo, 200 utenti a ciclo chiuso: changes p95 50 ms (1.891/s), commit 1 op p95 203 ms (627/s)</td><td>M4 + PG in Docker</td><td>indicativo, non il test richiesto</td></tr></tbody></table><h2 id="metriche-senza-obiettivo-nello-spec" tabindex="-1">Metriche senza obiettivo nello spec <a class="header-anchor" href="#metriche-senza-obiettivo-nello-spec" aria-label="Permalink to &quot;Metriche senza obiettivo nello spec&quot;">​</a></h2><p>Percorsi che lo spec non quantifica ma che crescono con il vault; misurati da <code>internal/perf/mutations_test.go</code> dopo l&#39;apertura nota. Le fasi modificano il dataset in cache e lo ripristinano: le note create vengono cancellate, le rinomine annullate byte per byte e l&#39;indice riallineato. <code>perfcheck</code> le elenca come <code>NEW</code> finché non sono nella baseline e non le fa mai fallire.</p><p>Dal 2026-11-01 sono nella baseline (<code>baseline-50000.json</code>, misura a macchina scarica dopo M11). Effetto delle ottimizzazioni M11-W4 a 50.000 note, prima → dopo: creazione nota 3091 → 47 ms, eliminazione 3083 → 57 ms, <code>PlanRename</code> 27,0 / 24,7 → 1,25 / 0,22 s, rinomina applicata 32,9 → 1,9 s, primo scan della sync 6,21 → 0,26 s, riconciliazione 3,39 → 0,62 s; indicizzazione completa 53,7 → 55,5 s con picco di memoria 160 → 69 MB.</p><p>W8 è stato confrontato con l&#39;albero precedente a 10.000 note in una sequenza A/B/A sulla stessa macchina: risultati uguali entro il rumore, tranne <code>plan_rename_leaf</code> (circa +12%, perché la rinomina ora esamina anche i canvas e i link nelle proprietà). Una misura a 50.000 note presa con la macchina carica (load 5–9) risultava uniformemente 1,6–2 volte più lenta anche sui percorsi non toccati: per le soglie va usata una misura a macchina scarica.</p><table tabindex="0"><thead><tr><th>Metrica</th><th>Cosa è cronometrato</th><th>Campioni</th><th>Prima (W4)</th></tr></thead><tbody><tr><td><code>note_create_index_median_ms</code> / <code>_p95_ms</code></td><td><code>Indexer.Update</code> di una nota appena creata (<code>WriteFile</code> con <code>create</code>, come <code>WriteNote</code> con hash vuoto) con due link e un link fantasma: insieme dei file cambiato → <code>links.ResolveAll</code> su tutto il vault</td><td>20</td><td>3.091 / 3.324 ms</td></tr><tr><td><code>note_delete_index_median_ms</code> / <code>_p95_ms</code></td><td><code>Indexer.Update</code> dopo la cancellazione di quelle note (stesso percorso di <code>Trash</code>)</td><td>20</td><td>3.083 / 3.129 ms</td></tr><tr><td><code>plan_rename_hub_median_ms</code></td><td><code>links.PlanRename</code> (anteprima di <code>LinksAPI.PlanRename</code>) delle note con più backlink</td><td>5 note</td><td>27,0 s</td></tr><tr><td><code>plan_rename_leaf_median_ms</code></td><td><code>links.PlanRename</code> di note casuali con 1-3 backlink</td><td>5 note</td><td>24,7 s</td></tr><tr><td><code>apply_rename_ms</code></td><td>come <code>LinksAPI.ApplyRename</code>: nuovo <code>PlanRename</code> + <code>ApplyRename</code> (riscrittura e spostamento) + <code>Indexer.Update</code> dei percorsi toccati, per la nota con circa 100 backlink (un hub ne ha migliaia a 50k)</td><td>1</td><td>32,9 s</td></tr><tr><td><code>apply_rename_leaf_ms</code></td><td>lo stesso per una nota con 1-3 backlink</td><td>1</td><td>34,2 s</td></tr><tr><td><code>sync_first_scan_s</code></td><td>primo ciclo di un <code>Engine</code> nuovo (come dopo l&#39;avvio) su un vault sincronizzato e invariato: righe <code>sync_files</code> già allineate, server finto senza modifiche; tempo da <code>Sync</code> alla prima richiesta di <code>changes</code></td><td>1</td><td>6,21 s</td></tr><tr><td><code>sync_rescan_unchanged_s</code></td><td>lo stesso, secondo ciclo dello stesso <code>Engine</code></td><td>1</td><td>0,22 s</td></tr></tbody></table><ul><li>Valori «Prima (W4)»: 2026-11-01, M4, Go 1.27.3, dataset 50k appena generato, load average 2,6-4,6 (nessuna build in parallelo); <code>.perf/results-before-50000.json</code>. Hub: 979-8.009 backlink, 2.531 note riscritte in media; il primo ciclo sync include 52 ms di pulizia dei temporanei.</li><li>La scansione non è esportata: si misura con <code>Engine.Sync</code> e un <code>Remote</code> finto che risponde solo a <code>changes</code> (vuoto); il primo ciclo include anche la pulizia dei file temporanei rimasti (una visita del vault, registrata a parte nel log del test).</li><li>Dopo una creazione il watcher dell&#39;app richiama <code>Update</code> sullo stesso percorso (contenuto identico, ricarica del resolver): non è nel tempo misurato.</li></ul><h2 id="ottimizzazioni-prima-→-dopo" tabindex="-1">Ottimizzazioni (prima → dopo) <a class="header-anchor" href="#ottimizzazioni-prima-→-dopo" aria-label="Permalink to &quot;Ottimizzazioni (prima → dopo)&quot;">​</a></h2><ul><li><strong>Indicizzazione.</strong> Profilo a 5.000 note: ~55 % del tempo nel commit WAL (una transazione per nota). Con batch da 250 note: 31 s → 5-8 s; poi il profilo ha mostrato <code>fts5IndexFlush</code> richiamato dal savepoint di ogni statement con foreign key dopo la prima scrittura FTS: scrivere le righe FTS alla fine del batch. A 50k: 72,6 s (carica). Prima: 2 h 23 min e solo 38.000 file su 50.000 (tempo di orologio, la macchina potrebbe aver dormito in parte).</li><li><strong>Salvataggio di una nota.</strong> <code>Update</code> rifaceva <code>ResolveAll</code> su tutto il vault: 280 ms a 5k note. Ora risolve solo i link della nota con il resolver in cache: 3,8 ms a 50k. La risoluzione completa resta quando una nota nuova/rimossa o gli alias cambiano (test <code>TestBatchesAndIncrementalResolve</code>).</li><li><strong>Ricerca.</strong> Profilo a 50k: ~50 % in <code>walBeginReadTransaction</code> (una query per corpo), poi lettura SQLite di ~170 MB a query. Passi: una sola transazione + corpo nella query di scansione (nessun guadagno netto sotto carico), cache dei candidati in RAM con valutazione parallela (1,8 s → 0,30 s per «budget review»), un solo <code>ToLower</code> per file e riga dello snippet tagliata dal corpo (→ 0,12 s). Tutte le query: 0,6-2,8 s → 0,03-0,14 s. <ul><li>Equivalenza: <code>TestQueryEquivalentToLegacy</code> confronta cache, streaming e strategia precedente su query casuali (e dopo modifiche/cancellazioni, per la cache incrementale): stessi hit, ordine, snippet, punteggi e totali. I test di ricerca esistenti passano invariati.</li></ul></li><li><strong>Albero.</strong> Finestra di rendering a righe fisse (vedi tabella).</li></ul><h2 id="cloud-k6" tabindex="-1">Cloud (k6) <a class="header-anchor" href="#cloud-k6" aria-label="Permalink to &quot;Cloud (k6)&quot;">​</a></h2><ul><li><p><code>services/cloud/test/load/k6/active-users.js</code>: fino a 1.000 utenti simulati (scenario <code>ramping-vus</code>), ciascuno con il proprio vault: polling di <code>changes</code> col cursore, commit di un piccolo file (create/modify) con upload del blob; 5 VU spediscono commit da 50 operazioni. Soglie k6: p95 <code>changes</code> &lt; 200 ms, p95 <code>commit</code> e <code>commit_batch50</code> &lt; 500 ms, errori &lt; 1 %.</p></li><li><p>Token: <code>TestServeLoadEnv</code> (<code>services/cloud/test/integration/loadenv_test.go</code>, tag <code>integration</code>, <strong>solo test</strong>: l&#39;issuer OIDC finto esiste solo nei binari di test) avvia API + PostgreSQL in container, crea N utenti con vault e scrive <code>tokens.json</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf-load-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> USERS=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # resta in attesa; fermare con: touch .perf/tokens.json.stop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">k6</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TOKENS=.perf/tokens.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> services/cloud/test/load/k6/active-users.js</span></span></code></pre></div></li><li><p><strong>Non eseguito qui.</strong> k6 non è installato; il binario scaricato non è stato eseguito (l&#39;esecuzione di codice esterno scaricato è stata rifiutata dal sistema di permessi). Verificati: sintassi JS (<code>node --check</code>), avvio dell&#39;ambiente (20 utenti creati in 0,2 s, token validi). Il nightly installa k6 con <code>grafana/setup-k6-action</code> e fa uno smoke da 200 utenti.</p></li><li><p><code>TestLoadSmallOps</code> (<code>CLARAE_LOAD=1</code>, anche con <code>CLARAE_LOAD_CPUPROFILE</code>) è il corrispettivo Go del mix «changes + commit piccoli». Con 32 client a ciclo chiuso il test M2 esistente satura (commit da 50 op p95 811 ms, tutti sullo stesso PG in Docker su un portatile carico): è un test di saturazione, non di 1.000 utenti reali (≈ 100 richieste/s).</p></li><li><p>Profilo del server sotto <code>TestLoadSmallOps</code>: il tempo è nei round trip verso PostgreSQL e nel <code>PutBlob</code> su filesystem; la compilazione degli schemi JSON per ogni richiesta (15 % della CPU) è nel client di test (<code>env.do</code>), non nel server. Nessun N+1 o contention evidente nei percorsi <code>changes</code>/<code>commit</code>: non è stato modificato codice del cloud.</p></li></ul><h2 id="limiti-noti" tabindex="-1">Limiti noti <a class="header-anchor" href="#limiti-noti" aria-label="Permalink to &quot;Limiti noti&quot;">​</a></h2><ul><li>Nessuna misura sulla webview reale (WebKit/WebView2): avvio a freddo end-to-end, digitazione e rendering vanno confermati a mano (checklist <code>docs/qa/parita-funzionale-m1.md</code>).</li><li>Regex su tutto il vault &gt; 200 ms (prefiltro sui letterali non implementato).</li><li>La cache di ricerca ha un costo in RAM pari al testo del vault (budget 512 MB, poi streaming).</li><li><code>index.db</code> ≈ 5,3× il testo; riconciliazione a vault invariato 3,5 s a 50k (in background).</li><li>Il dataset è sintetico (vocabolario di pseudo-parole): le dimensioni dei corpi e la distribuzione dei link sono realistiche, il testo no.</li></ul>`,21)])])}const h=i(n,[["render",s]]);export{u as __pageData,h as default};
